194	  // ---- renderQueueTable helpers (closure-scoped) ----------------------------
195	
196	  /** Removes the success banner from the preflight results area, if present.
197	   *  Error banners are intentionally left intact.
198	   *
199	   *  Closure dependency: `resultsEl` — the #orch-preflight-results element
200	   *  captured by renderOrchestrator() at line 64. */
201	  function _clearSuccessBanner() {
202	    var successBanner = resultsEl.querySelector('.success-banner');
203	    if (successBanner) {
204	      successBanner.remove();
205	    }
206	  }
